/**
 * The Worker's environment.
 *
 * `Env` is generated by `pnpm run types` from `wrangler.cloud.example.jsonc`, the superset
 * of both configurations. The local-mode configuration has no D1 database, no brain
 * container, no R2 bucket and no KEEP_AWAKE / SPINE_URL variables, so those are optional
 * here and every caller has to handle their absence. The inbox's rate limiters are optional
 * too (see `Limiters`).
 */

/** Names of the secrets handed to the brain container when they are set (cloud mode). */
export const BRAIN_SECRET_NAMES = [
  "ANTHROPIC_API_KEY",
  "ANTHROPIC_WORKSPACE_ID",
  "AWS_REGION",
  "AWS_ACCESS_KEY_ID",
  "AWS_SECRET_ACCESS_KEY",
  "AWS_BEARER_TOKEN_BEDROCK",
  "TELEGRAM_BOT_TOKEN",
  "TELEGRAM_ALLOWED_CHAT_IDS",
  "TAU_NET_IDENTITY",
  "TAU_LANG",
] as const;

export type BrainSecretName = (typeof BRAIN_SECRET_NAMES)[number];

/** Secrets are set with `wrangler secret put` (or `.dev.vars`), so any of them may be missing. */
export type SpineSecrets = { HUB_TOKEN?: string } & Partial<Record<BrainSecretName, string>>;

type CloudOnly = "DB" | "BRAIN" | "MEDIA" | "KEEP_AWAKE" | "SPINE_URL";

/**
 * The inbox's Rate Limiting bindings. A spine without them (an older configuration, or a
 * plan or runtime that lacks the binding) skips those checks and logs it once.
 */
type Limiters = "INBOX_IP_LIMIT" | "INBOX_SENDER_LIMIT";

export type SpineEnv = Omit<Env, CloudOnly | Limiters | "HUB_TOKEN"> &
  Partial<Pick<Env, CloudOnly | Limiters>> &
  SpineSecrets;

export type Mode = "local" | "cloud";

/** `TAU_MODE`; anything but "cloud" is local mode. */
export function modeOf(env: SpineEnv): Mode {
  return env.TAU_MODE === "cloud" ? "cloud" : "local";
}
